  // minimal stub: allocate and store config in session
  (void)config_json; return (Session*)malloc(sizeof(Session));
}

void destroy_session(Session* s){ if(s) free(s); }

char* analyze_batch(Session* s, const char** inputs, size_t n){
  // pretend JSON construction
  (void)s; (void)inputs; (void)n;
