## Why This Is Asked

This question tests practical CGO memory management and cross-language error handling, plus safe concurrency patterns.

## Key Concepts

- **CGO memory ownership**: Understanding who allocates and frees memory across the C/Go boundary
- **C string to Go string conversion**: Safely converting C strings to Go strings without dangling pointers
- **Error code mapping**: Translating C error codes to idiomatic Go errors
- **Concurrent CGO calls**: Properly handling CGO calls from goroutines

## Code Example

```c
// file.h
#ifndef FILE_H
#define FILE_H
#include <stddef.h>

const char* read_text_file(const char* path, int* err);
#endif
```

```c
// file.c
#include "file.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

const char* read_text_file(const char* path, int* err) {
    *err = 0;
    FILE* f = fopen(path, "rb");
    if (!f) {
        *err = 1; // Not found
        return NULL;
    }

    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);

    char* buf = malloc(len + 1);
    if (!buf) {
        *err = 3;
        fclose(f);
        return NULL;
    }

    fread(buf, 1, len, f);
    buf[len] = '\0';
    fclose(f);
    return buf;
}
```

```go
// file.go
package main

// #cgo CFLAGS: -I.
// #include "file.h"
import "C"
import (
    "errors"
    "fmt"
    "sync"
)

func ReadText(path string) (string, error) {
    cPath := C.CString(path)
    defer C.free(unsafe.Pointer(cPath))

    var err C.int
    result := C.read_text_file(cPath, &err)

    if result == nil {
        switch int(err) {
        case 1:
            return "", fmt.Errorf("file not found: %s", path)
        case 2:
            return "", fmt.Errorf("permission denied: %s", path)
        default:
            return "", errors.New("unknown error")
        }
    }

    goStr := C.GoString(result)
    C.free(unsafe.Pointer(result))
    return goStr, nil
}

func main() {
    var wg sync.WaitGroup

    for _, path := range []string{"file1.txt", "file2.txt"} {
        wg.Add(1)
        go func(p string) {
            defer wg.Done()
            content, err := ReadText(p)
            if err != nil {
                fmt.Printf("Error reading %s: %v\n", p, err)
                return
            }
            fmt.Printf("Read %d bytes from %s\n", len(content), p)
        }(path)
    }

    wg.Wait()
}
```

## Why This Is Asked
Tests ability to bridge Go and C with callbacks across threads, a common real-world CGO pitfall. It probes lifetime management, thread-safety, and CGO pointer rules.

## Key Concepts
- CGO callback lifetimes and //export limitations
- cg oHandle usage to store Go values for C callbacks
- Thread-safety: mutexes and safe dispatch of callbacks
- Proper cleanup to avoid leaks when unregistering

## Code Example
```javascript
// C header (capi.h)
typedef void (*cb_t)(int eventCode, void* context);
void register_cb(cb_t cb, void* ctx);
void emit_event(int code);
```

```javascript
// Go binding (cgowa/cgo) - simplified
package main
/*
#include "capi.h"
*/
import "C"
import (
  "sync"
  "unsafe"
)

var (
  mu       sync.Mutex
  cbStore  = map[uintptr]func(int){}
  nextKey  uintptr = 1
)

//export goCallback
func goCallback(event C.int, ctx unsafe.Pointer) {
  mu.Lock()
  if f, ok := cbStore[uintptr(ctx)]; ok {
    f(int(event))
  }
  mu.Unlock()
}

func registerCallback(f func(int)) unsafe.Pointer {
  mu.Lock()
  key := nextKey
  nextKey++
  cbStore[key] = f
  mu.Unlock()
  // pass key as ctx to C
  return unsafe.Pointer(uintptr(key))
}
```

```javascript
// Minimal usage (main.go)
package main
import (
  "C"
  "fmt"
)
func main(){
  cb := func(e int){ fmt.Println("event:", e) }
  ctx := registerCallback(cb)
  C.emit_event(42) // would trigger goCallback with ctx
  _ = ctx
}
```

