// Example program (main.go)
package main

import (
  "fmt"
  "sync"
  "./cgobox"
)

func main() {
  usernames := []string{"alice", "bob"}
  var wg sync.WaitGroup
  for _, u := range usernames {
    wg.Add(1)
    go func(name string) {
      defer wg.Done()
      info, err := cgobox.FetchUser(name)
      if err != nil {
        fmt.Println("err:", err)
        return
      }
      fmt.Printf("User: %+v\n", info)
    }(u)
  }
  wg.Wait()
}
